#!/usr/bin/env bash
# Checks a commit message: Conventional Commits subject and a DCO sign-off.
# Usage: scripts/check-commit-msg.sh <message-file>
set -euo pipefail
msg_file="$1"
subject="$(head -n1 "$msg_file")"

# Merge and revert commits generated by git are accepted as they are.
if [[ "$subject" =~ ^(Merge|Revert)\  ]]; then exit 0; fi

pattern='^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([a-z0-9/_-]+\))?!?: .{1,72}$'
if ! [[ "$subject" =~ $pattern ]]; then
  echo "Commit subject must follow Conventional Commits, e.g. 'feat(core): extract hashtags'." >&2
  echo "Got: $subject" >&2
  exit 1
fi
if ! grep -qE '^Signed-off-by: .+ <.+>$' "$msg_file"; then
  echo "Missing DCO sign-off. Commit with 'git commit -s' (see CONTRIBUTING.md)." >&2
  exit 1
fi
